const findMax = arr => {
  if (arr.length === 0) return undefined;

  let maxVal = arr[0];

  const updateMax = val => {
    if (val > maxVal) {
      maxVal = val;
    }
  };

  const processElement = element => updateMax(element);

  const iterateArray = array => array.forEach(processElement);

  iterateArray(arr.slice(1));

  const identity = x => x;

  return identity(maxVal);
};

