const multiplyByNineFifths = (celsius) => celsius * (9 / 5);

const addThirtyTwo = (fahrenheit) => fahrenheit + 32;

const celsiusToFahrenheit = (celsius) => {
  const fahrenheitMultiplied = multiplyByNineFifths(celsius);
  const finalFahrenheit = addThirtyTwo(fahrenheitMultiplied);
  return finalFahrenheit;
};

