  const fahrenheitTemp = celsiusToFahrenheit(celsiusTemp);
  console.log(`${celsiusTemp}°C is ${fahrenheitTemp}°F`);
};

const temperatures = [0, 25, -10];

const processTemperatures = (temps) => temps.forEach(temp => convertAndLog(temp));

processTemperatures(temperatures);

