const swapKeysAndValues = (obj) => {
  const entries = Object.entries(obj);

  const swapEntry = ([key, value]) => [value, key];

  const swappedEntries = entries.map(swapEntry);

  const createObject = (acc, [key, value]) => ({ ...acc, [key]: value });

  const newObj = swappedEntries.reduce(createObject, {});

  return newObj;
};

const example1 = { a: 1, b: 2 };
const example2 = { name: 'Alice', age: 30 };

const result1 = swapKeysAndValues(example1);
const result2 = swapKeysAndValues(example2);

console.log(result1); // { '1': 'a', '2': 'b' }
console.log(result2); // { Alice: 'name', '30': 'age' }

