  const charMap = {};
  for (const char of str) {
    charMap[char] = (charMap[char] || 0) + 1;
  }
  return charMap;
};

const compareCharMaps = (map1, map2) => {
  const keys1 = Object.keys(map1);
  const keys2 = Object.keys(map2);

  if (keys1.length !== keys2.length) return false;

  return keys1.every(key => map1[key] === map2[key]);
};

const areAnagrams = (str1, str2) => {
  const cleanedStr1 = normalizeString(str1);
  const cleanedStr2 = normalizeString(str2);

  if (cleanedStr1.length !== cleanedStr2.length) return false;

  const charMap1 = countChars(cleanedStr1);
  const charMap2 = countChars(cleanedStr2);

  return compareCharMaps(charMap1, charMap2);
};

const testAnagram = (s1, s2, expected) => {
  const result = areAnagrams(s1, s2);
  console.log(`'${s1}', '${s2}' -> ${result} (Expected: ${expected})`);
};

testAnagram('listen', 'silent', true);
testAnagram('hello', 'world', false);
testAnagram('Madam Curie', 'Radium came', true);
testAnagram('A gentleman', 'Elegant man', true);
testAnagram('Debit Card', 'Bad Credit', true);
testAnagram('hello', 'hell', false);

