const parseUrlParams = url => {
  const getQueryString = inputUrl => inputUrl.split('?')[1];
  const decode = s => decodeURIComponent(s.replace(/\+/g, ' '));

  const queryString = getQueryString(url);
  if (!queryString) return {};

  const splitParams = str => str.split('&');
  const parsePair = pair => {
    const [key, value] = pair.split('=');
    return [decode(key), decode(value || '')];
  };

  const paramPairs = splitParams(queryString);

  const reduceToObject = (acc, [key, value]) => ({ ...acc, [key]: value });

  return paramPairs
    .map(parsePair)
    .reduce(reduceToObject, {});
};

