const calculateDistance = (p1, p2) => {
  const diffX = p2.x - p1.x;
  const diffY = p2.y - p1.y;

  const square = val => val * val;

  const squaredDiffX = square(diffX);
  const squaredDiffY = square(diffY);

  const sumOfSquares = (a, b) => a + b;

  const totalSquaredDistance = sumOfSquares(squaredDiffX, squaredDiffY);

  const takeSquareRoot = val => Math.sqrt(val);

  return takeSquareRoot(totalSquaredDistance);
};

