    ...currentInventory,
    [itemName]: (currentInventory[itemName] || 0) + qtyToAdd,
  });

  const hasItem = (inv, itm) => Object.prototype.hasOwnProperty.call(inv, itm);

  const createNewInventory = (inv, itm, qty) => ({ ...inv, [itm]: qty });

  const processAddition = (inv, itm, qty) =>
    hasItem(inv, itm) ? updateItem(inv, itm, qty) : createNewInventory(inv, itm, qty);

  const applyQuantity = (inv, itm, qty) => processAddition(inv, itm, qty);

  return applyQuantity(inventory, item, quantity);
};

