  const sortedArr = sortAscending(arr);
  const midIndex = getMiddleIndex(sortedArr);

  return isEven(sortedArr.length)
    ? getAverage(sortedArr[midIndex - 1], sortedArr[midIndex])
    : sortedArr[midIndex];
};

