const truncateString = (str, maxLength) => {
  const isTooLong = s => s.length > maxLength;
  const sliceString = s => s.slice(0, maxLength - 3);
  const appendEllipsis = s => `${s}...`;

  const processLongString = s => appendEllipsis(sliceString(s));

  const identifyAndProcess = s => isTooLong(s) ? processLongString(s) : s;

  return identifyAndProcess(str);
};

