const sortNumbersAscending = arr => {
  const isNumber = val => typeof val === 'number';

  const filterNonNumbers = array => array.filter(isNumber);

  const createCopy = array => [...array];

  const compareNumbers = (a, b) => a - b;

  const sortArray = array => array.sort(compareNumbers);

  const processArray = input => {
    const numericArray = filterNonNumbers(input);
    const copiedArray = createCopy(numericArray);
    return sortArray(copiedArray);
  };

  return processArray(arr);
};

