const compressString = (str) => {
  if (!str) return str;

  let compressed = '';
  let count = 0;

  for (let i = 0; i < str.length; i++) {
    count++;
    if (i + 1 >= str.length || str[i] !== str[i + 1]) {
      compressed += str[i] + (count > 1 ? count.toString() : '');
      count = 0;
    }
  }

  const isShorter = (original, compressed) => compressed.length < original.length;
  return isShorter(str, compressed) ? compressed : str;
};

