const mergeObjects = (obj1, obj2) => {
  const assignProperties = (acc, key) => ({ ...acc, [key]: obj1[key] });
  const assignFromObj1 = Object.keys(obj1).reduce(assignProperties, {});

  const overwriteProperties = (acc, key) => ({ ...acc, [key]: obj2[key] });
  const assignFromObj2 = Object.keys(obj2).reduce(overwriteProperties, {});

  const merge = (o1, o2) => ({ ...o1, ...o2 });

  const finalMerge = merge(assignFromObj1, assignFromObj2);

  const filterEmpty = merged => Object.keys(merged).filter(key => merged[key] !== undefined).reduce((acc, key) => ({ ...acc, [key]: merged[key] }), {});

  return filterEmpty(finalMerge);
};

