const getFileExtension = (filename) => {
  const parts = filename.split('.');
  const hasMultipleParts = parts.length > 1;
  const getLastPart = (arr) => arr[arr.length - 1];
  const isExtensionPart = (part) => part !== '';

  return hasMultipleParts && isExtensionPart(getLastPart(parts))
    ? getLastPart(parts)
    : '';
};

